{"path": "/tmp/sv-b9f1e4116a754ca18b2291848953de69/Components/Pages/Settings/ProfileSection.razor", "file_text": "@namespace sv_b9f1e4116a754ca18b2291848953de69.Components.Pages.Settings
@using sv_b9f1e4116a754ca18b2291848953de69.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p>Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
