+    font-weight: 600;
+    color: #0d6efd;
+}
+
+.settings-nav-icon {
+    font-size: 1.2rem;
+}
+
+.settings-nav-label {
+    font-size: 0.95rem;
+}
+
+/* Content Area */
+.settings-content {
+    flex: 1;
+    padding: 2rem;
