+}
+
+.toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+.toast-error {
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
