+
+/* Toggle Switches */
+.toggle-group {
+    margin-bottom: 1rem;
+}
+
+.toggle-switch {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+}
+
+.toggle-switch input[type="checkbox"] {
+    width: 1.25rem;
+    height: 1.25rem;
