+
+.panel-header:hover {
+    background: rgba(0, 0, 0, 0.04);
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid var(--bs-border-color, #dee2e6);
+}
+
+/* Security Items */
+.security-item {
+    margin-bottom: 1.5rem;
+}
+
+.security-item h3 {
+    font-size: 1.1rem;
+    margin-bottom: 0.75rem;
+}
+
+.twofa-status {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.status-indicator {
+    padding: 0.25rem 0.75rem;
+    border-radius: 1rem;
+    font-size: 0.8rem;
+    font-weight: 600;
+}
+
+.status-active {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.status-inactive {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.meta-info {
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.5rem;
+}
+
+.current-session-badge {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.5rem;
+    background: #e2e3e5;
+    border-radius: 0.25rem;
+    color: #41464b;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
+}
+
+.sessions-table th {
+    font-weight: 600;
+    background: var(--bs-body-bg, #f8f9fa);
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1050;
+}
+
+.modal-dialog {
+    background: white;
+    border-radius: 0.5rem;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
+}
+
+.modal-dialog h3 {
+    margin-bottom: 0.75rem;
+}
+
+.modal-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    flex-wrap: wrap;
+}
+
+.radio-option {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+.radio-option input[type="radio"] {
+    accent-color: #0d6efd;
+}
+
+/* Live Preview */
+.live-preview {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid var(--bs-border-color, #dee2e6);
